    /// <summary>
    /// MPJ_5013_ExciseRegisterEntry
    /// </summary>
    public void dialogSelectCtrl()
    {
        //super();
        DialogField                         dialogUpdateNat3040;
        DialogField                         dialogNat3040Number;
        // get references to dialog controls after creation
        dialogUpdateNat3040 = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METNat3040RegisterUpdateContract, parmUpdateNat3040));

        dialogNat3040Number = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METNat3040RegisterUpdateContract, parmNat3040Number));

        if(dialogUpdateNat3040.value() == NoYes::Yes)
        {
           
            dialogNat3040Number.allowEdit(false);
        }
    }
